lib='''"""Reusable grid functions for ARC-style tasks."""
from collections import deque

def interior_cells(grid):
    """Nonzero cells whose 8 neighbors are all inside the grid and nonzero."""
    h, w = len(grid), len(grid[0]); cells = set()
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0 and all(
                0 <= i+dx < h and 0 <= j+dy < w and grid[i+dx][j+dy] != 0
                for dx in (-1, 0, 1) for dy in (-1, 0, 1) if dx or dy):
                cells.add((i, j))
    return cells

def components(cells):
    """Partition a set of (i, j) cells into 8-connected components (lists)."""
    un = set(cells); res = []
    while un:
        s = next(iter(un)); q = deque([s]); un.discard(s); comp = [s]
        while q:
            x, y = q.popleft()
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    a, b = x+dx, y+dy
                    if (a, b) in un:
                        un.discard((a, b)); comp.append((a, b)); q.append((a, b))
        res.append(comp)
    return res

def seeds(grid):
    """Cells whose color is neither the background 0 nor the fill color 1, with their colors."""
    return [(i, j, grid[i][j]) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] not in (0, 1)]

def geodesic(grid, src):
    """Shortest path lengths from src through nonzero cells (4-connectivity)."""
    h, w = len(grid), len(grid[0]); dist = {src: 0}; q = deque([src])
    while q:
        x, y = q.popleft()
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            a, b = x+dx, y+dy
            if 0 <= a < h and 0 <= b < w and grid[a][b] != 0 and (a, b) not in dist:
                dist[(a, b)] = dist[(x, y)] + 1; q.append((a, b))
    return dist

def paint_interiors(grid):
    """Recolor each 8-connected component of interior cells with the color of the geodesically nearest seed."""
    ss = seeds(grid)
    D = {s[:2]: geodesic(grid, s[:2]) for s in ss}
    out = [row[:] for row in grid]
    for comp in components(interior_cells(grid)):
        best = min(ss, key=lambda s: min(D[s[:2]].get(c, 10**9) for c in comp))
        for i, j in comp:
            out[i][j] = best[2]
    return out
'''
